actions.script:
String fileLocation = "component://${targetComponent}/${artifactPath}"

try {
    def resourceRef = ec.resource.getLocationReference(fileLocation)
    if (resourceRef && resourceRef.exists) {
        def xmlNode = new groovy.xml.XmlParser().parseText(resourceRef.getText())

        // Parse direct node hierarchy without legacy ScreenRenderImpl / DeterministicVueRenderer
        def parseWidgetNode
        parseWidgetNode = { node ->
            if (!(node instanceof groovy.util.Node)) return null
            String tagName = node.name().toString()
            if (['parameter', 'transition'].contains(tagName)) return null

            if (tagName == 'field') {
                String fieldName = node.attribute('name') ?: 'unnamed'
                List children = []
                node.children().each { c -> def mapped = parseWidgetNode(c); if (mapped) children.add(mapped) }
                return [type: "FormField", name: fieldName, title: node.attribute('title') ?: fieldName, mariaId: fileLocation + "#" + fieldName, children: children]
            } else {
                String nodeId = node.attribute('id') ?: node.attribute('name') ?: (tagName + "_" + java.util.UUID.randomUUID().toString().take(8))
                List children = []
                node.children().each { c -> def mapped = parseWidgetNode(c); if (mapped) children.add(mapped) }
                return [type: tagName, id: nodeId, mariaId: fileLocation + "#" + nodeId, children: children]
            }
        }

        List rootWidgets = []
        def widgetsNode = xmlNode.widgets[0]
        if (widgetsNode) {
            widgetsNode.children().each { child ->
                def mapped = parseWidgetNode(child)
                if (mapped) rootWidgets.add(mapped)
            }
        }

        context.blueprintJson = [
            screen: artifactPath.split('/')[-1].replace(".xml", ""),
            location: fileLocation,
            mariaId: artifactPath.split('/')[-1].replace(".xml", "") + "#root",
            widgets: rootWidgets
        ]
    } else {
        context.blueprintJson = [widgets: []]
    }
} catch (Exception e) {
    ec.logger.error("❌ [AGI-IDE SERVICE ERROR] Failed to parse XML blueprint: " + e.getMessage(), e)
    context.blueprintJson = [name: "Error", attributes: [text: e.getMessage()]]
}

String fileLocation = screenPath
def componentName = "agi-ide"
ec.logger.info("🔍 [DEBUG FormMetadata] Input screenPath: ${screenPath}")

try {
    def resourceRef = ec.resource.getLocationReference(fileLocation)

    if (!resourceRef || !resourceRef.exists) {
        String cleanFileName = fileLocation.contains("/") ? fileLocation.split('/')[-1] : fileLocation
        fileLocation = "component://${componentName}/screen/${cleanFileName}"
        resourceRef = ec.resource.getLocationReference(fileLocation)
    }

    if (resourceRef && resourceRef.exists) {
        String xmlContent = resourceRef.getText()
        String artifactFileName = fileLocation.substring(fileLocation.lastIndexOf("/") + 1)

        // 1. Attempt rendering via get#XmlArtifactBlueprint
        Map blueprintResult = ec.service.sync()
            .name("org.moqui.ide.AgiMcpServices.get#XmlArtifactBlueprint")
            .parameter("targetComponent", componentName)
            .parameter("artifactPath", "screen/" + artifactFileName)
            .call()

        Map blueprintJson = blueprintResult?.blueprintJson

        // 2. Direct XML Parser Fallback if blueprint rendering is missing fields
        if (!blueprintJson || blueprintJson.name == "Error" || !blueprintJson.widgets || blueprintJson.widgets.isEmpty()) {
            ec.logger.warn("⚠️ [DEBUG FormMetadata] Executing structured XML Screen parser...")

            def xmlNode = new groovy.xml.XmlParser().parseText(xmlContent)

            // Recursive closure to map Moqui screen widgets into Blueprint nodes
            def parseWidgetNode
            parseWidgetNode = { node ->
                if (!(node instanceof groovy.util.Node)) return null

                String tagName = node.name().toString()

                // Ignore top-level metadata tags that aren't UI widgets
                if (['parameter', 'transition'].contains(tagName)) return null

                if (tagName == 'field') {
                    String fieldName = node.attribute('name') ?: 'unnamed'
                    String fieldTitle = node.attribute('title') ?: fieldName

                    List widgetChildren = []
                    node.children().each { child ->
                        def childMapped = parseWidgetNode(child)
                        if (childMapped) widgetChildren.add(childMapped)
                    }

                    return [
                        type: "FormField",
                        name: fieldName,
                        title: fieldTitle,
                        mariaId: fileLocation + "#" + fieldName,
                        children: widgetChildren
                    ]
                } else {
                    String nodeId = node.attribute('id') ?: node.attribute('name') ?: (tagName + "_" + java.util.UUID.randomUUID().toString().take(8))

                    List widgetChildren = []
                    node.children().each { child ->
                        def childMapped = parseWidgetNode(child)
                        if (childMapped) widgetChildren.add(childMapped)
                    }

                    return [
                        type: tagName,
                        id: nodeId,
                        name: node.attribute('name') ?: nodeId,
                        mariaId: fileLocation + "#" + nodeId,
                        children: widgetChildren
                    ]
                }
            }

            List rootWidgets = []
            // Locate the <widgets> section inside <screen>
            def widgetsNode = xmlNode.widgets[0]
            if (widgetsNode) {
                widgetsNode.children().each { child ->
                    def mapped = parseWidgetNode(child)
                    if (mapped) rootWidgets.add(mapped)
                }
            }

            blueprintJson = [
                screen: artifactFileName.replace(".xml", ""),
                location: fileLocation,
                mariaId: artifactFileName.replace(".xml", "") + "#root",
                widgets: rootWidgets
            ]
        }

        metadataJson = groovy.json.JsonOutput.toJson(blueprintJson)
        ec.logger.info("🎯 [DEBUG FormMetadata] Final Structured MetaJSON generated successfully!")
    } else {
        ec.logger.error("❌ [DEBUG FormMetadata] Resource does not exist on disk for: ${screenPath}")
        metadataJson = '{"error": "Target layout asset file not found on disk context."}'
    }
} catch (Exception ex) {
    ec.logger.error("❌ [DEBUG FormMetadata] Exception caught during compilation pass", ex)
    metadataJson = '{"error": "Exception occurred during direct screen compilation pass. See server console logs."}'
}
